package com.osrsevents;

import com.google.gson.annotations.SerializedName;
import java.util.List;
import lombok.AllArgsConstructor;

final class ApiModels
{
	private ApiModels()
	{
	}

	@AllArgsConstructor
	static class Item
	{
		final int id;
		final String name;
		final int quantity;
	}

	static class Context
	{
		String source;
		@SerializedName("npc_id")
		Integer npcId;
		@SerializedName("npc_name")
		String npcName;
		@SerializedName("npc_level")
		Integer npcLevel;
		@SerializedName("kill_count")
		Integer killCount;
		@SerializedName("region_id")
		Integer regionId;
		List<Item> items;
	}

	@AllArgsConstructor
	static class Completion
	{
		@SerializedName("client_event_id")
		final String clientEventId;
		final String kind;
		final String name;
		final int quantity;
		final String rsn;
		@SerializedName("occurred_at")
		final String occurredAt;
		final Context context;
	}

	/** The character this client is signed in as, for POST /identity. */
	@AllArgsConstructor
	static class Identity
	{
		final String rsn;
	}

	static class EventsResponse
	{
		String mode;
		String rsn;
		/** Whether a client has ever reported this account playing `rsn`. */
		boolean proven;
		List<EventInfo> events;
		List<Verdict> reviews;
		List<String> watch;
	}

	static class EventInfo
	{
		List<Object> targets;
	}

	static class Verdict
	{
		String id;
		String label;
		@SerializedName("event_title")
		String eventTitle;
		String status;
	}

	static class CompletionResponse
	{
		boolean duplicate;
		List<Claim> claims;
		/** Counted targets this report moved without claiming: "2 / 5". */
		List<Progress> progress;
	}

	static class Progress
	{
		@SerializedName("event_title")
		String eventTitle;
		String label;
		String name;
		int done;
		@SerializedName("required_count")
		int requiredCount;
	}

	static class Claim
	{
		@SerializedName("event_title")
		String eventTitle;
		String label;
		String name;
		String status;
	}

	static class ErrorResponse
	{
		String message;
	}
}

package com.osrsevents;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * The "Your X kill count is: N" family of game messages.
 *
 * The wording is not one sentence but several, and guessing at it was wrong
 * twice: the descriptor sits in front of the name as often as behind it
 * ("Your completed Chambers of Xeric count is:", "Your subdued Wintertodt
 * count is:", "Your completion count for Barrows is:"), the middle word is
 * not always "kill" (harvest, lap, completion, success, Total Ticket), and
 * the number can arrive wrapped in an @col@ marker rather than a tag.
 *
 * This mirrors KILLCOUNT_PATTERN in RuneLite's own ChatCommandsPlugin
 * (client 1.12.39), which is maintained against the live game. Do not tighten
 * it from memory — read that file.
 */
final class KillCount
{
	/**
	 * Both halves are optional on their own, and a line with neither is not a
	 * kill count at all — "Your poisoned karambwan is: ..." would otherwise
	 * parse. RuneLite draws the same line for the same reason.
	 */
	/**
	 * Counters that do not use the sentence above at all. Each one is its own
	 * wording in the game, so each one is its own pattern; RuneLite keeps them
	 * apart for the same reason.
	 *
	 * The name is the **wiki page title**, not the name RuneLite files the
	 * count under, because the server matches a report against the title of a
	 * wiki-linked task. Those differ: RuneLite says "Hunter Rumours", the wiki
	 * page is "Hunters' Rumours", and after normalising apostrophes away that
	 * is still "hunter rumours" against "hunters rumours" — a square would
	 * never match.
	 */
	private static final Pattern RUMOURS = Pattern.compile(
		"You have completed (?:@[^@]+@)?(?<count>[0-9,]+) rumours? for the Hunter Guild");

	private static final Pattern RIFTS = Pattern.compile(
		"Amount of Rifts you have closed: (?:@[^@]+@)?(?<count>[0-9,]+)", Pattern.CASE_INSENSITIVE);

	/**
	 * A full run: the coffin is opened once at the end of one. A square that
	 * means "do the Sepulchre N times" means this.
	 */
	private static final Pattern COFFIN = Pattern.compile(
		"You have opened the Grand Hallowed Coffin (?:@[^@]+@)?(?<count>[0-9,]+) times?");

	/**
	 * One floor, counted per floor.
	 *
	 * Every floor carries its **own** total, so naming each floor separately
	 * is what keeps them apart — floor 1 at 50 and floor 5 at 50 are two
	 * different targets, not the same count twice. That makes "run floor 1
	 * twenty times" expressible, which one shared name could never be.
	 *
	 * The reported name is not a wiki page and does not have to be: a task
	 * links a wiki page, but its title is free text, and the title is what a
	 * report is matched against. A square for this carries the title
	 * "Hallowed Sepulchre Floor 1".
	 */
	private static final Pattern FLOOR = Pattern.compile(
		"You have completed Floor (?<floor>[0-9]+) of the Hallowed Sepulchre! "
			+ "Total completions: (?:@[^@]+@)?(?<count>[0-9,]+)");

	private static final Pattern PATTERN = Pattern.compile(
		"Your (?<pre>completion count for |subdued |completed )?(?<name>.+?) "
			+ "(?<post>(?:(?:kill|harvest|lap|completion|success|Total Ticket) )?(?:count )?)"
			+ "is: ?(?:@[^@]+@)?(?<count>[0-9,]+)");

	static final class Parsed
	{
		final String name;
		final int count;

		private Parsed(String name, int count)
		{
			this.name = name;
			this.count = count;
		}
	}

	private KillCount()
	{
	}

	/** The message with its tags already stripped, or null when it is not one of these. */
	static Parsed parse(String message)
	{
		Parsed named = named(message);
		if (named != null)
		{
			return named;
		}

		Matcher matcher = PATTERN.matcher(message);

		if (!matcher.find())
		{
			return null;
		}

		String pre = matcher.group("pre");
		String post = matcher.group("post");

		if ((pre == null || pre.isEmpty()) && (post == null || post.isEmpty()))
		{
			return null;
		}

		return new Parsed(matcher.group("name"), Integer.parseInt(matcher.group("count").replace(",", "")));
	}

	/** The counters whose wording carries no name, so the name is ours to supply. */
	private static Parsed named(String message)
	{
		Parsed rumours = match(RUMOURS, message, "Hunters' Rumours");
		if (rumours != null)
		{
			return rumours;
		}

		Parsed rifts = match(RIFTS, message, "Guardians of the Rift");
		if (rifts != null)
		{
			return rifts;
		}

		Parsed coffin = match(COFFIN, message, "Grand Hallowed Coffin");
		if (coffin != null)
		{
			return coffin;
		}

		Matcher floor = FLOOR.matcher(message);

		return floor.find()
			? new Parsed("Hallowed Sepulchre Floor " + floor.group("floor"),
				Integer.parseInt(floor.group("count").replace(",", "")))
			: null;
	}

	private static Parsed match(Pattern pattern, String message, String name)
	{
		Matcher matcher = pattern.matcher(message);

		return matcher.find()
			? new Parsed(name, Integer.parseInt(matcher.group("count").replace(",", "")))
			: null;
	}
}

package com.osrsevents;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import org.junit.Test;

/**
 * The wordings here are the ones RuneLite's own ChatCommandsPlugin matches
 * (client 1.12.39). They are not guesses, and a change to this parser starts
 * by reading that file again.
 */
public class KillCountTest
{
	private static KillCount.Parsed parse(String message)
	{
		// The plugin strips tags before parsing; these are the stripped lines.
		return KillCount.parse(message.replaceAll("<[^>]*>", ""));
	}

	@Test
	public void readsAPlainKillCount()
	{
		KillCount.Parsed parsed = parse("Your Zalcano kill count is: 383.");

		assertNotNull(parsed);
		assertEquals("Zalcano", parsed.name);
		assertEquals(383, parsed.count);
	}

	@Test
	public void readsAColouredCount()
	{
		assertEquals(1234, parse("Your Zalcano kill count is: <col=ff0000>1,234</col>.").count);
		assertEquals(1234, parse("Your Zalcano kill count is: @red@1,234</col>.").count);
	}

	/** The descriptor sits in front of the name as often as behind it. */
	@Test
	public void readsTheDescriptorsThatComeFirst()
	{
		assertEquals("Chambers of Xeric", parse("Your completed Chambers of Xeric count is: 5.").name);
		assertEquals("Wintertodt", parse("Your subdued Wintertodt count is: 50.").name);
		assertEquals("Barrows", parse("Your completion count for Barrows is: 12.").name);
	}

	/** "kill" is not the only middle word. */
	@Test
	public void readsTheOtherMiddleWords()
	{
		assertEquals("Barrows chest", parse("Your Barrows chest count is: 12.").name);
		assertEquals("Tempoross", parse("Your Tempoross kill count is: 100.").name);
		assertEquals("Hespori", parse("Your Hespori harvest count is: 8.").name);
		assertEquals("Prifddinas Agility Course", parse("Your Prifddinas Agility Course lap count is: 200.").name);
		assertEquals("Gauntlet", parse("Your Gauntlet completion count is: 30.").name);
		assertEquals("Yama", parse("Your Yama success count is: 4.").name);
	}

	/** A line with no descriptor at all is some other message, not a kill count. */
	@Test
	public void ignoresALineThatOnlyLooksLikeOne()
	{
		assertNull(parse("Your reward is: 500 coins."));
		assertNull(parse("You have killed 5 chickens."));
	}

	/**
	 * Counters with a wording of their own. The name is the wiki page title,
	 * because that is what a task links and what the server matches against —
	 * RuneLite's own "Hunter Rumours" would never match a square titled after
	 * the wiki's "Hunters' Rumours".
	 */
	@Test
	public void readsTheCountersWithTheirOwnWording()
	{
		KillCount.Parsed rumours = parse("You have completed @red@12</col> rumours for the Hunter Guild.");
		assertEquals("Hunters' Rumours", rumours.name);
		assertEquals(12, rumours.count);

		assertEquals("Hunters' Rumours", parse("You have completed @red@1</col> rumour for the Hunter Guild.").name);

		KillCount.Parsed rifts = parse("Amount of Rifts you have closed: <col=ff0000>1,234</col>.");
		assertEquals("Guardians of the Rift", rifts.name);
		assertEquals(1234, rifts.count);

		KillCount.Parsed coffin = parse("You have opened the Grand Hallowed Coffin <col=ff0000>57</col> times!");
		assertEquals("Grand Hallowed Coffin", coffin.name);
		assertEquals(57, coffin.count);

		assertEquals(1, parse("You have opened the Grand Hallowed Coffin <col=ff0000>1</col> time!").count);
	}

	/**
	 * Each floor counts on its own, which is what makes "run floor 1 twenty
	 * times" expressible. The name is not a wiki page title and does not need
	 * to be — a task links a page, but its title is free text and the title
	 * is what a report is matched against.
	 */
	@Test
	public void countsEachSepulchreFloorSeparately()
	{
		KillCount.Parsed first = parse("You have completed Floor 1 of the Hallowed Sepulchre! Total completions: <col=ff0000>50</col>.");
		assertEquals("Hallowed Sepulchre Floor 1", first.name);
		assertEquals(50, first.count);

		KillCount.Parsed fifth = parse("You have completed Floor 5 of the Hallowed Sepulchre! Total completions: <col=ff0000>50</col>.");
		assertEquals("Hallowed Sepulchre Floor 5", fifth.name);
		assertEquals(50, fifth.count);
	}
}

package com.osrsevents;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/** Same cases as the server's RunelitePluginApiTest::names. */
public class NameMatcherTest
{
	private static void same(String game, String wiki)
	{
		assertEquals(NameMatcher.normalize(wiki), NameMatcher.normalize(game));
	}

	private static void different(String game, String wiki)
	{
		assertNotEquals(NameMatcher.normalize(wiki), NameMatcher.normalize(game));
	}

	@Test
	public void matchesTheServer()
	{
		same("Pet snakeling", "Pet Snakeling");
		same("  Dragon   bones ", "Dragon bones");
		same("Abyssal_whip", "Abyssal whip");
		same("Karil’s coif", "Karil's coif");
		same("Karils coif", "Karil's coif");
		same("Prayer potion(4)", "Prayer potion");
		same("Games necklace (8)", "Games necklace");
		same("<col=ff9040>Giant Mole</col>", "Giant Mole");
		same("Giant Mole", "Giant Mole");
		different("Clue scroll (medium)", "Clue scroll");
		different("Berserker ring (i)", "Berserker ring");
		different("Dragon bones", "Big bones");
		assertEquals("karils coif", NameMatcher.normalize("Karil's coif"));
	}

	@Test
	public void rsnComparesLikeTheGame()
	{
		assertTrue(OsrsEventsPlugin.sameRsn("Iron Kettle", "iron_kettle"));
		assertTrue(OsrsEventsPlugin.sameRsn("Iron-Kettle", "Iron Kettle"));
		assertFalse(OsrsEventsPlugin.sameRsn("Kettle", "Zezima"));
	}
}

